def build_agent(sandbox):
    # Create a robust hull with sufficient height to clear pillars and maintain buoyancy
    hull = sandbox.add_beam(x=5.0, y=1.0, width=2.0, height=1.5, angle=0, density=50.0)
    sandbox.set_material_properties(hull, restitution=0.05)
    return hull

def agent_action(sandbox, agent_body, step_count):
    if agent_body is None or not agent_body.active:
        return
    front_x = sandbox.get_vehicle_front_x() or agent_body.position.x
    target_x = 26.0
    if front_x >= target_x + 0.1:
        return

    in_danger_zone = (16.5 <= front_x <= 19.5)

    # Apply thrust if cooldown allows
    if step_count % 18 == 0:
        # Apply thrust in positive x direction
        sandbox.apply_force(agent_body, 520.0, 0.0, step_count=step_count)

        # Apply lift force in deep channel
        if in_danger_zone:
            sandbox.apply_force(agent_body, 0.0, 400.0, step_count=step_count)
